import { MongoClient, ServerApiVersion } from "mongodb";
import { EJSON } from "bson";
// Generated by backend/scripts/setup_qe.py and copied in here because the
// Docker image only contains frontend/. keyIds are not secret.
import encryptedFieldsJson from "@/lib/const/qeEncryptedFields.json";

// Dedicated client for the Queryable Encryption explorer. The app's main client
// has no autoEncryption, so queries against customer_db_encrypted through it
// return raw ciphertext. This client carries the key vault + encryptedFieldsMap,
// so ssn / billing_amount are encrypted on query and decrypted on return.
//
// Requires:
//   QE_MASTER_KEY       hex-encoded 96-byte local KMS master key (see
//                       backend/scripts/setup_qe.py, backend/qe_masterkey.txt)
//   CRYPT_SHARED_PATH   path to the crypt_shared library (automatic encryption
//                       needs it for query analysis)

const KEY_VAULT_NAMESPACE = "encryption.__keyVault";
const ENCRYPTED_COLLECTION = "customer_db_encrypted";

// keyId is stored as EJSON ($binary) — deserialize so the driver gets real
// BSON Binary values rather than plain objects.
const encryptedFields = EJSON.parse(JSON.stringify(encryptedFieldsJson), {
  relaxed: false,
});

let clientPromise;

export function qeConfigError() {
  if (!process.env.QE_MASTER_KEY) {
    return "QE_MASTER_KEY is not set — the Queryable Encryption demo needs the local master key created by backend/scripts/setup_qe.py.";
  }
  if (!process.env.CRYPT_SHARED_PATH) {
    return "CRYPT_SHARED_PATH is not set — automatic encryption needs the crypt_shared library.";
  }
  return null;
}

export default function getQeClientPromise() {
  if (clientPromise) return clientPromise;

  const dbName = process.env.DATABASE_NAME;
  const namespace = `${dbName}.${ENCRYPTED_COLLECTION}`;

  const client = new MongoClient(process.env.MONGODB_URI, {
    appName: "smartgrid-qe",
    serverApi: { version: ServerApiVersion.v1, strict: false, deprecationErrors: true },
    autoEncryption: {
      keyVaultNamespace: KEY_VAULT_NAMESPACE,
      kmsProviders: {
        local: { key: Buffer.from(process.env.QE_MASTER_KEY, "hex") },
      },
      encryptedFieldsMap: { [namespace]: encryptedFields },
      extraOptions: {
        cryptSharedLibPath: process.env.CRYPT_SHARED_PATH,
        cryptSharedLibRequired: true,
      },
    },
  });

  clientPromise = client.connect();
  return clientPromise;
}
